const body = $json.body ?? $json;
const operation = body.operation;
if (!['chat', 'chat_guard', 'evaluation', 'questionnaire_generation', 'questionnaire_evaluation'].includes(operation)) throw new Error('Unsupported operation');
if (typeof body.system !== 'string' || !body.system.trim()) throw new Error('system is required');
if (typeof body.message !== 'string' || !body.message.trim()) throw new Error('message is required');
if (operation.startsWith('questionnaire_')) {
  const generation = operation === 'questionnaire_generation';
  const limit = generation ? 64000 : 96000;
  const maxTokens = generation ? 4096 : 8192;
  if (body.system.length + body.message.length > limit) throw new Error('Assessment input too large');
  if (!['gpt-4o', 'gpt-4o-mini'].includes(body.model)) throw new Error('Unsupported assessment model');
  if (body.maxTokens !== maxTokens) throw new Error('Invalid assessment token cap');
  if (!Array.isArray(body.history) || body.history.length !== 0) throw new Error('Assessment history is not allowed');
  for (const text of [body.system, body.message]) {
    for (let i = 0; i < text.length; i++) {
      const c = text.charCodeAt(i);
      if (c === 0) throw new Error('Invalid assessment Unicode');
      if (c >= 0xD800 && c <= 0xDBFF) {
        const next = text.charCodeAt(++i);
        if (!(next >= 0xDC00 && next <= 0xDFFF)) throw new Error('Invalid assessment Unicode');
      } else if (c >= 0xDC00 && c <= 0xDFFF) throw new Error('Invalid assessment Unicode');
    }
  }
  return [{ json: { operation, system: body.system, prompt: body.message, model: body.model, maxTokens, temperature: 0 } }];
}
const history = Array.isArray(body.history) ? body.history.slice(-10).flatMap(item => {
  if (!item || !['user', 'assistant'].includes(item.role) || typeof item.content !== 'string' || !item.content.trim()) return [];
  return [`${item.role}: ${item.content.trim().slice(0, 4000)}`];
}) : [];
const message = body.message.trim().slice(0, 12000);
const prompt = [...history, `user: ${message}`].join('\n');
const maxTokens = Math.min(Math.max(Math.trunc(Number(body.maxTokens)) || 512, 1), 2048);
return [{ json: {
  operation,
  system: body.system.trim().slice(0, 60000),
  prompt,
  model: typeof body.model === 'string' && body.model.trim() ? body.model.trim() : 'gpt-4o-mini',
  maxTokens,
  temperature: operation === 'chat' ? 0.4 : 0
} }];

const assessment = $('Prepare Input').item.json.operation.startsWith('questionnaire_');
if (assessment) {
  const raw = $json.output ?? $json.text ?? $json.message?.content;
  if (typeof raw !== 'string' || !raw.trim() || raw.length > 131072) throw new Error('Invalid assessment response');
  return [{ json: { message: raw } }];
}
const raw = String($json.output ?? $json.text ?? $json.message?.content ?? '').trim();
if (!raw) throw new Error('OpenAI returned no message');
const message = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
return [{ json: { message } }];
